import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Drawer.stories";
import Drawer from "./Drawer";

const { Basic } = composeStories(stories) as any;

describe("Drawer component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("hides its children when closed", () => {
    const { baseElement } = render(
      <Drawer open={false}>
        <p data-testid="drawer-content">Lorem ipsum dolor sit amet</p>
      </Drawer>
    );
    expect(baseElement).toMatchInlineSnapshot(`
      <body>
        <div />
      </body>
    `);
  });

  it("shows its children when open", () => {
    const { baseElement } = render(
      <Drawer open={true}>
        <p data-testid="drawer-content">Lorem ipsum dolor sit amet</p>
      </Drawer>
    );
    expect(baseElement).toMatchSnapshot();
    expect(screen.getByTestId("drawer-content")).toHaveTextContent(
      "Lorem ipsum dolor sit amet"
    );
  });

  it("closes when the backdrop is clicked", () => {
    const handleClose = jest.fn();
    const { baseElement } = render(
      <Drawer open={true} onClose={handleClose}>
        <p data-testid="drawer-content">Lorem ipsum dolor sit amet</p>
      </Drawer>
    );
    // eslint-disable-next-line testing-library/no-node-access
    fireEvent.click(baseElement.querySelector("[aria-hidden]") as Element);
    expect(handleClose).toHaveBeenCalled();
  });

  it("closes when ESC is pressed", () => {
    const handleClose = jest.fn();
    render(
      <Drawer open={true} onClose={handleClose}>
        <p data-testid="drawer-content">Lorem ipsum dolor sit amet</p>
        <button>foo</button>
      </Drawer>
    );
    fireEvent.keyDown(screen.getByTestId("drawer-content"), { keyCode: 27 });
    expect(handleClose).toHaveBeenCalled();
  });

  it("passes through props", () => {
    render(<Drawer open data-testid="drawer"></Drawer>);
    expect(screen.queryByRole("presentation")).toHaveAttribute(
      "data-testid",
      "drawer"
    );
  });
});
